 require_once(__DIR__.'/engine/engine.php'); class map_tables_editor { public function loadData ($params) { return Engine::load($params); } public function saveData ($params) { return Engine::save($params); } public function printTable ($params) { $fullAnalytics = isUndefinedProperty($params, 'fullAnalytics'); $printParams = isUndefinedProperty($params, 'printParams'); $params = Engine::load($params, true); $params->analytics = $fullAnalytics; $params->printParams = $printParams; Printer::printTable($params); } public function import ($params) { return Engine::import($params); } } if ($_POST && isset($_POST['download']) && isset($_POST['print']) && isset($_POST['args'])) { $service = new map_tables_editor(); $args = safe_json_decode($_POST['args']); $service->printTable($args); } else { $service = new Junior\Server(new map_tables_editor()); $service->process(); } 